# Check the functional equation for S={1, 2}
# Let c0, c1, c2, c12 be the colors of subsets {}, {1}, {2}, {1, 2} respectively.
# The equation is: (c0 + c1)(c0 + c2) = c0 * (c0 + c1 + c2 + c12)

count = 0
for c0 in [0, 1]:
    for c1 in [0, 1]:
        for c2 in [0, 1]:
            for c12 in [0, 1]:
                LHS = (c0 + c1) * (c0 + c2)
                RHS = c0 * (c0 + c1 + c2 + c12)
                if LHS == RHS:
                    count += 1

print(f"Total number of solutions: {count}")
